122	                  [attr.data-testid]="'person-edit-' + p.id"
123	                  [attr.aria-label]="'Edit ' + p.name"
124	                  (click)="edit(p)"
125	                >
126	                  Edit
127	                </button>
128	                <button
129	                  type="button"
130	                  data-testid="person-statement"
131	                  [attr.aria-label]="'Take statement for ' + p.name"
132	                  (click)="statement(p)"
133	                >
134	                  Statement
135	                </button>
136	                <label [for]="'person-retire-date-' + p.id">Retire from</label>
137	                <input
138	                  type="date"
139	                  [id]="'person-retire-date-' + p.id"
140	                  data-testid="person-retire-date"
141	                  #retireDate
142	                  (input)="personError.set(null)"
143	                />
144	                <button
145	                  type="button"
146	                  data-testid="person-retire"
147	                  [attr.aria-label]="'Retire ' + p.name"
148	                  (click)="retire(p, retireDate.value)"
149	                >
150	                  Retire
151	                </button>
152	                <button
153	                  type="button"
154	                  data-testid="person-hold-toggle"
155	                  [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name"
156	                  (click)="hold(p)"
157	                >
158	                  {{ p.held ? 'Release' : 'Hold' }}
159	                </button>
160	                <label [for]="'person-patron-select-' + p.id">Patron</label>
161	                <select
162	                  [id]="'person-patron-select-' + p.id"
163	                  data-testid="person-patron-select"
164	                  #patronSelect
165	                  (change)="patronError.set(null)"
166	                >
167	                  @for (o of people(); track o.id) {
168	                    @if (o.id !== p.id) {
169	                      <option [value]="o.id">{{ o.name }}</option>
170	                    }
171	                  }
172	                </select>
173	                <button
174	                  type="button"
175	                  data-testid="person-patron-add"
176	                  [attr.aria-label]="'Add patron for ' + p.name"
177	                  (click)="addPatron(p, patronSelect.value)"
178	                >
179	                  Add patron
180	                </button>
181	                @if (patronError()?.id === p.id) {
182	                  <p role="alert" data-testid="person-patron-error">{{ patronError()?.message }}</p>
183	                }
184	                @if (personError()?.id === p.id) {
185	                  <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
186	                }
187	              </td>
188	            </tr>
189	          }
190	        </tbody>
191	      </table>
192	    </section>
193	  `,
194	})
195	export class People {
196	  private readonly session = inject(Session);
197	  private readonly api = inject(PeopleApi);
198	  private readonly claimsApi = inject(ClaimsApi);
199	  private readonly ratesApi = inject(RatesApi);
200	  private readonly periodsApi = inject(PeriodsApi);
201	  private readonly floor = inject(SheetFloor);
202	  private readonly terms = inject(SheetTerms);
203	  private readonly latePct = inject(SheetLatePct);
204	  /** What a late charge goes by: the sheet's today, terms and late percent. */
205	  private readonly late = computed<Lateness>(() => ({
206	    today: this.session.today(),
207	    terms: this.terms.value(),
208	    latePct: this.latePct.value(),
209	  }));
210	
211	  protected readonly grades: Grade[] = ['A', 'B', 'C'];
212	  protected readonly people = signal<Person[]>([]);
213	  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
214	  protected readonly showRetired = signal(false);
215	  /** The people listed: everyone, or only those not retired unless retired people are shown. Totals count
216	   * everyone either way. */
217	  protected readonly shownPeople = computed(() =>
218	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retiredFrom),
219	  );
220	  /** The sheet's claims, newest first. */
221	  protected readonly claims = signal<Claim[]>([]);
222	  private readonly claimsByPerson = computed(() => {
223	    const by = new Map<number, Claim[]>();
224	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
225	    return by;
226	  });
227	  /** The ids of the people on hold, whose OPEN claims count in no total. */
228	  private readonly heldIds = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
229	  protected readonly claimedTotal = computed(() =>
230	    sumAmounts(this.claims().filter((c) => this.countsLive(c)).map((c) => c.amount)),
231	  );
232	  /** The sheet's rates. */
233	  protected readonly rates = signal<Rate[]>([]);
234	  /** The rate each grade with one has in force on the sheet's today. */
235	  protected readonly rateByGrade = computed(() => {
236	    const today = this.session.today() ?? '';
237	    const by = new Map<Grade, string>();
238	    for (const g of this.grades) {
239	      const rate = rateOn(this.rates(), g, today);
240	      if (rate !== undefined) by.set(g, rate);
241	    }
242	    return by;
243	  });
244	
245	  /** The sheet's periods by from-date. */
246	  protected readonly periods = signal<Period[]>([]);
247	  /** Each period's due-total, by id: the sum of the dues of the claims that count dated in it (n/a ones
248	   * skipped), 0.00 with none; a closed period's is the one fixed when it closed. */
249	  protected readonly periodDueTotals = computed(() => {
250	    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
251	    const dues = new Map<number, string[]>();
252	    for (const c of this.claims().filter((c) => this.countsLive(c))) {
253	      const period = periodOf(this.periods(), c.date);
254	      const grade = grades.get(c.personId);
255	      if (!period || !grade) continue;
256	      const due = claimDue(c, this.rates(), grade, this.floor.value(), this.late());
257	      if (due !== NO_RATE) dues.set(period.id, [...(dues.get(period.id) ?? []), due]);
258	    }
259	    return new Map(this.periods().map((p) => [p.id, p.closedTotal ?? sumAmounts(dues.get(p.id) ?? [])]));
260	  });
261	
262	  protected readonly dueTotal = computed(() =>
263	    sumAmounts(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
264	  );
265	  /** How many of the sheet's claims that count are overdue, and the sum of their dues (n/a ones skipped). */
266	  protected readonly overdueCount = computed(() =>
267	    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
268	  );
269	  protected readonly overdueTotal = computed(() => sumAmounts(this.people().map((p) => this.overdueTotalOf(p))));
270	  protected readonly editingId = signal<number | null>(null);
271	  /** The version of the person the editor loaded. */
272	  private editingVersion: number | null = null;
273	  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
274	  private submitting = false;
275	  protected readonly formError = signal<string | null>(null);
276	  /** The error of the last action taken on a person's row, shown on that row. */
277	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
278	  /** The error of the last patron added on a person's row, shown on that row. */
279	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
280	  protected readonly form = new FormGroup({
281	    name: new FormControl('', { nonNullable: true }),
282	    grade: new FormControl<Grade>('A', { nonNullable: true }),
283	  });
284	
285	  /** Whether a quick-add is waiting on the server; another is ignored until it answers. */
286	  private quickAdding = false;
287	  protected readonly quickError = signal<string | null>(null);
288	  protected readonly quickForm = new FormGroup({
289	    name: new FormControl('', { nonNullable: true }),
290	    amount: new FormControl('', { nonNullable: true }),
291	  });
292	
293	  constructor() {
294	    this.form.valueChanges.subscribe(() => this.formError.set(null));
295	    this.quickForm.valueChanges.subscribe(() => this.quickError.set(null));
296	    // Re-read the sheet's people and their claims from the store each time a sheet is loaded.
297	    toObservable(this.session.sheetId)
298	      .pipe(
299	        switchMap((id) =>
300	          id
301	            ? forkJoin({
302	                people: this.api.list(id),
303	                claims: this.claimsApi.list(id),
304	                rates: this.ratesApi.list(id),
305	                periods: this.periodsApi.list(id),
306	              })
307	            : of({ people: [] as Person[], claims: [] as Claim[], rates: [] as Rate[], periods: [] as Period[] }),
308	        ),
309	      )
310	      .subscribe(({ people, claims, rates, periods }) => {
311	        this.people.set(people);
312	        this.periods.set(periods);
313	        this.claims.set(claims);
314	        this.rates.set(rates);
315	        this.reset();
316	      });
317	  }
318	
319	  protected claimsOf(personId: number): Claim[] {
320	    return this.claimsByPerson().get(personId) ?? [];
321	  }
322	
323	  protected claimed(personId: number): string {
324	    return sumAmounts(this.claimsOf(personId).filter((c) => this.countsLive(c)).map((c) => c.amount));
325	  }
326	
327	  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
328	   * person whose grade has no rate in force on the sheet's today shows n/a, unless a settled or stated claim
329	   * keeps a figure. */
330	  protected personDueTotal(person: Person): string {
331	    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
332	    const frozen = counted.some(keepsFigure);
333	    if (!this.rateByGrade().has(person.grade) && !frozen) return NO_RATE;
334	    return sumAmounts(
335	      counted.map((c) => claimDue(c, this.rates(), person.grade, this.floor.value(), this.late())).filter((d) => d !== NO_RATE),
336	    );
337	  }
338	
339	  /** The person's claims that count and are overdue. */
340	  protected overdueOf(person: Person): Claim[] {
341	    const today = this.session.today();
342	    return this.claimsOf(person.id).filter((c) => this.countsLive(c) && isOverdue(c, this.terms.value(), today));
343	  }
344	
345	  /** The sum of the dues of the person's overdue claims that count (n/a ones skipped), 0.00 with none. */
346	  protected overdueTotalOf(person: Person): string {
347	    return sumAmounts(
348	      this.overdueOf(person)
349	        .map((c) => claimDue(c, this.rates(), person.grade, this.floor.value(), this.late()))
350	        .filter((d) => d !== NO_RATE),
351	    );
352	  }
353	
354	  /** The names of the person's patrons, sorted, comma and space separated. */
355	  protected patronNames(person: Person): string {
356	    return this.patronsOf(person)
357	      .map((p) => p.name)
358	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
359	      .join(', ');
360	  }
361	
362	  /** The person's backing: their patrons' due-totals added up (n/a ones skipped), 0.00 with no patrons. */
363	  protected backing(person: Person): string {
364	    return sumAmounts(this.patronsOf(person).map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
365	  }
366	
367	  private patronsOf(person: Person): Person[] {
368	    const byId = new Map(this.people().map((p) => [p.id, p]));
369	    return person.patronIds.map((id) => byId.get(id)).filter((p): p is Person => p !== undefined);
370	  }
371	
372	  /** Name another person on the sheet as the person's patron. */
373	  protected addPatron(person: Person, patronId: string): void {
374	    this.patronError.set(null);
375	    this.personError.set(null);
376	    const sheetId = this.session.sheetId();
377	    if (!sheetId) return;
378	    if (!patronId) {
379	      this.patronError.set({ id: person.id, message: 'Choose a patron.' });
380	      return;
381	    }
382	    this.api.addPatron(sheetId, person.id, Number(patronId)).subscribe({
383	      next: (p) => {
384	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
385	      },
386	      error: (e: HttpErrorResponse) =>
387	        this.patronError.set({
388	          id: person.id,
389	          message:
390	            e.status === 409
391	              ? 'That person is already a patron.'
392	              : e.status === 422
393	                ? 'A person cannot be their own patron.'
394	                : e.status === 404
395	                  ? 'That person is no longer on this sheet.'
396	                  : 'Could not add that patron.',
397	        }),
398	    });
399	  }
400	
401	  /** Whether a claim counts in the live totals: it counts, and is not an OPEN claim of a held person. */
402	  private countsLive(claim: Claim): boolean {
403	    return counts(claim) && !(claim.status === 'OPEN' && this.heldIds().has(claim.personId));
404	  }
405	
406	  protected rateSaved(rate: Rate): void {
407	    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
408	  }
409	
410	  protected periodSaved(period: Period): void {
411	    this.periods.update((ps) =>
412	      [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : 1)),
413	    );
414	  }
415	
416	  protected claimSaved(claim: Claim): void {
417	    this.claims.update((cs) =>
418	      cs.some((c) => c.id === claim.id) ? cs.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...cs],
419	    );
420	  }
421	
422	  /** Take a statement for the person, then re-read the sheet's claims, which it binds or unbinds. */
423	  protected statement(person: Person): void {
424	    this.personError.set(null);
425	    this.patronError.set(null);
426	    const sheetId = this.session.sheetId();
427	    if (!sheetId) return;
428	    this.api
429	      .statement(sheetId, person.id)
430	      .pipe(switchMap((p) => forkJoin({ person: of(p), claims: this.claimsApi.list(sheetId) })))
431	      .subscribe({
432	        next: ({ person: p, claims }) => {
433	          if (this.session.sheetId() !== sheetId) return;
434	          this.claims.set(claims);
435	          this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
436	        },
437	        error: (e: HttpErrorResponse) =>
438	          this.personError.set({
439	            id: person.id,
440	            message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not take that statement.',
441	          }),
442	      });
443	  }
444	
445	  protected toggleRetired(event: Event): void {
446	    this.showRetired.set((event.target as HTMLInputElement).checked);
447	  }
448	
449	  /** Retire the person from the date given, the sheet's today when none is. */
450	  protected retire(person: Person, from: string): void {
451	    this.personError.set(null);
452	    this.patronError.set(null);
453	    const sheetId = this.session.sheetId();
454	    if (!sheetId) return;
455	    this.api.retire(sheetId, person.id, from || null).subscribe({
456	      next: (p) => {
457	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
458	      },
459	      error: (e: HttpErrorResponse) =>
460	        this.personError.set({
461	          id: person.id,
462	          message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not retire that person.',
463	        }),
464	    });
465	  }
466	
467	  /** Put the person on hold, or take them off it when held. */
468	  protected hold(person: Person): void {
469	    this.personError.set(null);
470	    this.patronError.set(null);
471	    const sheetId = this.session.sheetId();
472	    if (!sheetId) return;
473	    this.api.hold(sheetId, person.id).subscribe({
474	      next: (p) => {
475	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
476	      },
477	      error: (e: HttpErrorResponse) =>
478	        this.personError.set({
479	          id: person.id,
480	          message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not change that hold.',
481	        }),
482	    });
483	  }
484	
485	  /** Add a draft claim for the named person, who is added first when not on the sheet. */
486	  protected quickAdd(): void {
487	    if (this.quickAdding) return;
488	    this.quickError.set(null);
489	    const sheetId = this.session.sheetId();
490	    if (!sheetId) {
491	      this.quickError.set('Load a sheet first.');
492	      return;
493	    }
494	    const value = this.quickForm.getRawValue();
495	    if (!value.name.trim()) {
496	      this.quickError.set('Type a name for the person.');
497	      return;
498	    }
499	    this.quickAdding = true;
500	    this.api.quickAdd(sheetId, value).subscribe({
501	      next: ({ person, personCreated, claim }) => {
502	        this.quickAdding = false;
503	        if (this.session.sheetId() !== sheetId) return;
504	        if (personCreated) this.people.update((ps) => [...ps, person]);
505	        this.claimSaved(claim);
506	        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
507	      },
508	      error: (e: HttpErrorResponse) => {
509	        this.quickAdding = false;
510	        this.quickError.set(this.quickRefusal(e));
511	      },
512	    });
513	  }
514	
515	  private quickRefusal(e: HttpErrorResponse): string {
516	    if (e.status === 400) return 'Type a name and an amount of 0.00 or more, with up to two decimals.';
517	    if (e.status === 423) return 'The sheet\'s today is in a closed period.';
518	    if (e.status === 422) return 'That person is retired from before the sheet\'s today.';
519	    return 'Could not add that claim.';
520	  }
521	
522	  protected edit(person: Person): void {
523	    this.personError.set(null);
524	    this.patronError.set(null);
525	    this.editingId.set(person.id);
526	    this.editingVersion = person.version;
527	    this.form.setValue({ name: person.name, grade: person.grade }, { emitEvent: false });
528	    this.formError.set(null);
529	  }
530	
531	  protected reset(): void {
532	    this.editingId.set(null);
533	    this.editingVersion = null;
534	    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
535	    this.formError.set(null);
536	  }
537	
538	  protected submit(): void {
539	    if (this.submitting) return;
540	    this.formError.set(null);
541	    const sheetId = this.session.sheetId();
542	    if (!sheetId) {
543	      this.formError.set('Load a sheet first.');
544	      return;
545	    }
546	    const value = this.form.getRawValue();
547	    if (!value.name.trim()) {
548	      this.formError.set('Type a name for the person.');
549	      return;
550	    }
551	    const id = this.editingId();
552	    this.submitting = true;
553	    const done = () => (this.submitting = false);
554	    if (id === null) {
555	      this.api.add(sheetId, value).subscribe({
556	        next: (p) => {
557	          done();
558	          if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, p]);
559	          this.reset();
560	        },
561	        error: (e: HttpErrorResponse) => {
562	          done();
563	          this.formError.set(this.refusal(e, 'Could not add that person.'));
564	        },
565	      });
566	    } else {
567	      this.api.update(sheetId, id, { ...value, version: this.editingVersion ?? undefined }).subscribe({
568	        next: (p) => {
569	          done();
570	          if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
571	          this.reset();
572	        },
573	        error: (e: HttpErrorResponse) => {
574	          done();
575	          if (e.status === 412) {
576	            this.formError.set('Someone else has saved this person since you opened it. Their values are shown.');
577	            this.showCurrent(sheetId, id);
578	          } else {
579	            this.formError.set(this.refusal(e, 'Could not save that person.'));
580	          }
581	        },
582	      });
583	    }
584	  }
585	
586	  /** Re-read the person from the store and show their current values in the editor, keeping its error. */
587	  private showCurrent(sheetId: string, id: number): void {
588	    this.api.list(sheetId).subscribe((people) => {
589	      if (this.session.sheetId() !== sheetId) return;
590	      this.people.set(people);
591	      const current = people.find((p) => p.id === id);
592	      if (current && this.editingId() === id) {
593	        this.editingVersion = current.version;
594	        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
595	      }
596	    });
597	  }
598	
599	  private refusal(e: HttpErrorResponse, fallback: string): string {
600	    return e.status === 409 ? 'That name is already in use on this sheet.' : fallback;
601	  }
602	}
